def render_product_details(product):
    slug,name,trade,group,*_=product
    item=DETAILS[slug]
    rows=list(item['rows'])+EXTRA_ROWS.get(slug,[])
    if not any(row[0] == CROP[0] for row in rows):
        rows.append(CROP)
    rows += [
      ('Packing & quantity','Bag / container type, net weight and order quantity','Final packing is agreed with the quotation.'),
      ('Testing & documents','Required analysis, sample and destination documentation','Required reports or certificates must be confirmed for the specific lot.'),
    ]
    if slug in QUALITY_OPTIONS:
        options='; '.join(QUALITY_OPTIONS[slug])
        explanation='Commercial quality options confirmed by Shiva Exim. Lot specifications and destination requirements are agreed with the quotation.' if slug!='alfalfa-seeds' else 'Commercial quality options confirmed by Shiva Exim. Confirm the variety, intended growing region and lot test report separately.'
        rows.insert(0,('Listed quality options',options,explanation))
    table=''.join('<tr>'+''.join(f'<th scope="row">{escape(cell)}</th>' if i==0 else f'<td>{escape(cell)}</td>' for i,cell in enumerate(row))+'</tr>' for row in rows)
    note=f'<p class="product-specific-note">{escape(item["note"])}</p>' if item['note'] else ''
    if slug in ['cumin-seeds','fennel-seeds']:
        note+='<p class="product-specific-note">Europe quality and Singapore quality are listed commercial grade options. Required purity results, other quality limits and destination compliance are confirmed for the offered lot. These spice grades do not establish germination or suitability for sowing. For a planting enquiry, specify the variety, growing region and required lot-specific seed tests separately.</p>'
    key='spices' if group in ['Whole spices','Ground spices'] else 'planting' if slug in ['alfalfa-seeds','onion-seeds'] else 'millet' if slug in ['foxtail-millet','green-millet'] else 'oil' if slug=='olive-oil' else 'soybean' if slug=='soybean' else 'maize' if slug=='maize' else 'mustard' if slug=='mustard-seeds' else None
    source=f'<p class="technical-source">Parameter reference: <a href="{SOURCES[key][1]}" target="_blank" rel="noopener">{SOURCES[key][0]} ↗</a>. This reference does not imply certification of Shiva Exim or any offered lot.</p>' if key else ''
    status='Listed quality options are confirmed by Shiva Exim. Detailed limits, packing and lot test results are confirmed in the final offer.' if slug in QUALITY_OPTIONS else 'Product form, quality limits, availability and lot test results are agreed with the final offer.'
    return f'''<section class="product-information wrap" aria-label="{escape(name)} description and specification guide"><div class="product-overview"><div><span class="eyebrow">UNDERSTAND THE PRODUCT</span><h2>Product description</h2>{quality_labels(slug)}{identity_html(slug)}<p>{escape(item['description'])}</p>{note}</div><aside><h3>Common applications</h3><p>{escape(item['uses'])}</p><h3>Specification status</h3><p>{status}</p></aside></div><div class="specification-heading"><span class="eyebrow">QUALITY & COMMERCIAL DETAILS</span><h2>Specification guide</h2><p>Use these parameters to tell us what you need. They are not claims about current stock.</p></div><div class="specification-table-wrap"><table class="specification-table"><caption>{escape(name)} — parameters to agree before ordering</caption><thead><tr><th scope="col">Parameter</th><th scope="col">What to specify</th><th scope="col">Why it matters</th></tr></thead><tbody>{table}</tbody></table></div>{source}<div class="specification-actions"><a class="button" href="/contact/?product={slug}&intent={'buy' if trade=='export' else 'supply'}">Discuss this specification ↗</a><p>Send your target values or a buyer specification sheet with your enquiry.</p></div></section>'''+sowing_guidance_html(slug)+buying_guide_html(product)
